pub fn selected_tree(
    head: &[(&str, &str)],
    work: &[(&str, &str)],
    selected: &[&str],
) -> Vec<(String, String)> {
    let mut tree: std::collections::BTreeMap<String, String> = head
        .iter()
        .map(|(k, v)| (k.to_string(), v.to_string()))
        .collect();
    let work: std::collections::BTreeMap<_, _> =
        work.iter().copied().collect();
    for path in selected {
        if let Some(value) = work.get(path) {
            tree.insert(path.to_string(), value.to_string());
        } else {
            tree.remove(*path);
        }
    }
    tree.into_iter().collect()
}

fn main() {
    assert_eq!(
        selected_tree(
            &[("a", "old"), ("b", "old")],
            &[("a", "new"), ("b", "secret")],
            &["a"]
        ),
        vec![
            ("a".to_owned(), "new".to_owned()),
            ("b".to_owned(), "old".to_owned())
        ],
        "case 1"
    );
    assert_eq!(
        selected_tree(&[], &[("a", "x")], &[]),
        vec![],
        "case 2"
    );
    assert_eq!(
        selected_tree(&[("a", "x")], &[], &["a"]),
        vec![],
        "case 3"
    );
    assert_eq!(
        selected_tree(&[], &[("b", "x")], &["b", "b"]),
        vec![("b".to_owned(), "x".to_owned())],
        "case 4"
    );
    println!("worked example passed");
}

